/**
 * Storno z detailu objednavky (2026). Na rozdil od orders.php a order_edit.php
 * nesaha primo do tabulky: stornuje novy e-shop, ten uvolni rezervace
 * ve skladu a spocita castku k vraceni.
 */
public function cancelAction()
{
    if (!is_post()) {
        return $this->notFound('Storno jde jen odeslat formulářem');
    }

    global $db;
    legacy_db();

    $id = (string) post_param('id');
    if (!Uuid::isValid($id)) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }
    $order = $db->one("SELECT * FROM orders WHERE id = " . $db->quote($id));
    if ($order === null) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }
    if ($order['status'] == 'cancelled') {
        flash('Objednávka už je stornovaná', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    $reason = trim((string) post_param('reason'));
    if ($reason == '') {
        $reason = 'storno z administrace';
    }

    try {
        $envelope = $GLOBALS['LEGACY_COMMAND_BUS']->dispatch(new CancelOrder(OrderId::fromString($id), $reason));
    } catch (HandlerFailedException $e) {
        $cause = $e->getPrevious();
        if (!$cause instanceof InvalidOrderStateTransitionException) {
            throw $e;
        }
        flash('Objednávku ve stavu „' . order_state_label($order['status']) . '“ nelze stornovat', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    /** @var Money $refund */
    $refund = $envelope->last(HandledStamp::class)->getResult();
    $refundText = format_price($refund->amountInCents, $refund->currency->value);

    audit_log('order', $id, 'storno', array(
        'from'   => $order['status'],
        'reason' => $reason,
        'refund' => $refund->amountInCents,
    ));

    $c = $db->one("SELECT email FROM customers WHERE id = " . $db->quote($order['customer_id']));
    if ($c) {
        $body = "Dobrý den,\n\nvaše objednávka " . $id . " byla stornována.\n";
        if ($refund->amountInCents > 0) {
            $body .= "Zaplacenou částku " . $refundText . " vám vrátíme na účet.\n";
        }
        send_mail($c['email'], 'Objednávka byla stornována', $body);
    }

    cache_delete('dashboard_stats');

    if ($refund->amountInCents > 0) {
        flash('Objednávka stornována, zboží vráceno na sklad. Vraťte zákazníkovi ' . $refundText . '.');
    } else {
        flash('Objednávka stornována, zboží vráceno na sklad. Nebyla zaplacena, nic se nevrací.');
    }

    return $this->redirect(admin_url('order', array('id' => $id)));
}

